class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        n = len(coins)
        hi = min(coins) * k
        LIMIT = hi

        # Build (lcm, sign) for all nonempty subsets, pruning lcm > LIMIT
        terms = []  # list of (lcm, sign)
        # Iterative subset generation with pruning
        # Each state: (lcm_value, size_parity_sign) where sign = +1 for odd size, -1 for even size
        current = [(1, 0)]  # (lcm, size) with empty set having lcm 1, size 0
        for c in coins:
            new_entries = []
            for (l, sz) in current:
                g = gcd(l, c)
                nl = l // g * c
                if nl <= LIMIT:
                    new_entries.append((nl, sz + 1))
            current.extend(new_entries)
        for (l, sz) in current:
            if sz == 0:
                continue
            sign = 1 if sz % 2 == 1 else -1
            terms.append((l, sign))

        def count(x: int) -> int:
            total = 0
            for l, s in terms:
                total += s * (x // l)
            return total

        lo, hi_b = 1, hi
        while lo < hi_b:
            mid = (lo + hi_b) // 2
            if count(mid) >= k:
                hi_b = mid
            else:
                lo = mid + 1
        return lo
