        n = len(coins)
        high = k * min(coins)
        # Precompute subset LCMs (with sign) for all non-empty subsets
        # Capping: if lcm exceeds high, it contributes 0 to counts, so we can drop it.
        pos = []
        neg = []
        # lcm_of[mask] computed incrementally; use None for "too large"
        lcm_of = [0] * (1 << n)
        lcm_of[0] = 1
        for mask in range(1, 1 << n):
            low_bit = mask & -mask
            idx = low_bit.bit_length() - 1
            prev = mask ^ low_bit
            pl = lcm_of[prev]
            if pl is None:
                lcm_of[mask] = None
                continue
            c = coins[idx]
            l = pl // gcd(pl, c) * c
            if l > high:
                lcm_of[mask] = None
            else:
                lcm_of[mask] = l
                if bin(mask).count("1") % 2 == 1:
                    pos.append(l)
                else:
                    neg.append(l)

        def count(x: int) -> int:
            total = 0
            for l in pos:
                total += x // l
            for l in neg:
                total -= x // l
            return total

        lo, hi = 1, high
        while lo < hi:
            mid = (lo + hi) // 2
            if count(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo
